    free(p->idx);
    if (!p->ents) return;
    if (__builtin_expect(vu_drop_depth < VU_MAX_DROP_DEPTH, 1)) { vu_drop_depth++; vu_freeents_M3_StrS_Inst(p->ents, p->nents); vu_drop_depth--; }
